<?php $title = 'Administração'; ?><section class="container page-head"><p class="eyebrow">Moderação</p><h1>Anúncios pendentes</h1><p>Revise os anúncios antes de publicá-los.</p></section><section class="container section"><div class="property-grid"><?php foreach ($properties as $property): ?><article class="property-card"><div class="property-body"><span class="tag">Pendente</span><h3><?= Helper::e($property['titulo']) ?></h3><p class="muted"><?= Helper::e($property['cidade']) ?> · <?= Helper::e($property['categoria']) ?></p><p><?= Helper::e(mb_strimwidth($property['descricao'], 0, 120, '...')) ?></p><a class="button" href="<?= Helper::e(Helper::url('admin/aprovar?id=' . $property['id'])) ?>">Aprovar</a></div></article><?php endforeach; ?></div></section>